diff --git a/src/butil/popen.cpp b/src/butil/popen.cpp
new file mode 100644
index 0000000000..9daf92018e
--- /dev/null
+++ b/src/butil/popen.cpp
@@ -0,0 +1,178 @@
+// Copyright (c) 2017 Baidu.com, Inc. All Rights Reserved
+// 
