 namespace os {

+// Set the ownership for a path. This function never follows any symlinks.
 inline Try<Nothing> chown(
     uid_t uid,
     gid_t gid,
     const std::string& path,
     bool recursive)
 {
-  if (recursive) {
-    // TODO(bmahler): Consider walking the file tree instead. We would need
