+    bool nestedRole = strings::contains(config.role(), "/");
+    if (nestedRole) {
+      return BadRequest(
+          "Updating quota on nested role '" + config.role() +
+          "' is not supported yet");
+    }
+
+    Option<Error> error = quota::validate(config);
+
+    if (error.isSome()) {
+      return BadRequest(
+          "Invalid QuotaConfig: " + error->message);
+    }
+  }
+
+  return NotImplemented();
+}
