+  ASSERT_SOME_EQ("../../d/e", path::relative("a/d/e", "a/b/c"));
+
+  // Check for behavior of not normalized paths.
+  ASSERT_SOME_EQ(".", path::relative("/a/./b", "/a/b"));
+}
